import hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];HERE=Path(__file__).resolve().parent;OUT=ROOT/'experiments/records/lp2-shifted-page-pair-differences';OUT.mkdir(parents=True,exist_ok=True)
alphabet='ᚠᚢᚦᚩᚱᚳᚷᚹᚻᚾᛁᛄᛇᛈᛉᛋᛏᛒᛖᛗᛚᛝᛟᛞᚪᚫᚣᛡᛠ';index={c:i for i,c in enumerate(alphabet)}
pages=[];pins=[]
for n in range(56):
    path=ROOT/'text'/f'lp2-{n:02d}.txt';raw=path.read_bytes();vals=[index[c] for c in raw.decode('utf-8') if c in index]
    if vals:
        pages.append({'id':f'lp2-{n:02d}','runes':vals});pins.append({'path':path.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(raw).hexdigest()})
assert len(pages)==55
(OUT/'pages.json').write_text(json.dumps(pages,indent=2)+'\n',encoding='utf-8',newline='\n')
plan={'source_id':'B-14','source_commit':'f08b20b632d91209ddbaa747e8e2f23df0c78ba1','proposal':'AUTO_EVOLUTION.md S1: all pages/all offsets/difference-IoC shared-keystream search','existing_overlap':'lp2-page-pair-alignment and lp2-page-pair-english only test zero offset. This grid includes1326 same-direction zero-offset differences for baseline parity and330582 new nonzero-lag alignments; no claim of new manuscript texts.','pages_sha256':hashlib.sha256((OUT/'pages.json').read_bytes()).hexdigest(),'input_text_pins':pins,'minimum_overlap':120,'direction':'forward only','operation':'(page_a-page_b) mod29','pairs':'unordered distinct pairs; sign reversal gives same IoC','lag_convention':'start_a=max(lag,0);start_b=max(-lag,0);overlap=min(len(a)-start_a,len(b)-start_b)','lag_range':'-(len(b)-120) through len(a)-120 inclusive','cell_count':331908,'eligible_pages':52,'pair_count':1326,'nonzero_lag_cells':330582,'rune_comparisons_per_grid':60392906,'null_trials':128,'null_seed':330120261024,'null':'Shuffle each complete page once per trial, independently across pages; reuse same shuffled pages over all pairs/lags. Preserve each page length and rune histogram, not every overlap-window histogram.','statistic':'maximum unscaled IoC sum(n_r*(n_r-1))/(L*(L-1)) over complete grid','decision':'Compare observed global maximum to128 null global maxima; report plus-one empirical exceedance (1+k)/129. No plaintext or generator-family exclusion.','positive_controls':{'seed':330124,'page_lengths':[277,277],'lags':[1,37,-53],'constant_difference':7,'minimum_planted_overlap':224,'require':'unique expected shifted constant-difference peak reaches IoC1; independently counted; shuffled copy control must lose IoC1'},'independent_checker':'Recount every observed alignment with direct slice/count arithmetic; verify baseline zero-offset parity, all planted lags and every null-winning alignment, and recount global empirical comparison. Full128-null rerun uses runner --check.','limits':['No page reversal, wrapping, repeated key, key skipping, English scoring or arbitrary substrings shorter than120.','IoC is concentration, not a universal detector of shared random keys over unrelated plaintexts.','Whole-page permutation is a declared structural reference, not a generative model of LP2.']}
for target in [HERE/'plan-frozen.json',OUT/'plan.json']:
    assert not target.exists(),'Frozen plan exists; do not overwrite after observations'
    target.write_text(json.dumps(plan,indent=2)+'\n',encoding='utf-8',newline='\n')
(HERE/'plan-sha256.txt').write_text(hashlib.sha256((OUT/'plan.json').read_bytes()).hexdigest()+'\n',encoding='ascii')
